"""Deterministic extraction of the repository retriever's pre-rerank filter."""

from types import SimpleNamespace


def handle(value):
    hits = value["hits"]
    if value.get("representation", "mapping") == "attribute":
        hits = [SimpleNamespace(**hit) for hit in hits]
    cutoff = value.get("distance_cutoff")
    if cutoff is not None:
        hits = [
            hit
            for hit in hits
            if getattr(hit, "distance", None) is not None
            and hit.distance <= cutoff
        ]
    return {
        "ids": [hit["id"] if isinstance(hit, dict) else hit.id for hit in hits]
    }

