import unittest

from component import handle


class RetrievalFilterTests(unittest.TestCase):
    def test_attribute_hits_obey_cutoff(self):
        self.assertEqual(
            handle({
                "representation": "attribute",
                "hits": [{"id": "near", "distance": 0.2}, {"id": "far", "distance": 0.8}],
                "distance_cutoff": 0.4,
            }),
            {"ids": ["near"]},
        )

    def test_no_cutoff_preserves_input_order(self):
        self.assertEqual(
            handle({"hits": [{"id": "second"}, {"id": "first", "distance": 0.7}]}),
            {"ids": ["second", "first"]},
        )


if __name__ == "__main__":
    unittest.main()
